unordered_map<char, int> window;
int left = 0, best = 0;
for (int right = 0; right < s.size(); right++) {
    window[s[right]]++;                 // extend
    while (!isValid(window)) {          // WHILE, not if
        if (--window[s[left]] == 0) window.erase(s[left]);
        left++;
    }
    best = max(best, right - left + 1);
}

// Fixed window of size k: add one, drop one, no inner loop.
for (int right = 0; right < s.size(); right++) {
    add(s[right]);
    if (right >= k) remove(s[right - k]);   // element falling out of the back
    if (right >= k - 1) check();            // window is exactly k wide here
}

