def checkInclusion(s1, s2):
    if len(s1) > len(s2):
        return False
    s1_count = [0] * 26
    window = [0] * 26
    for c in s1:
        s1_count[ord(c) - ord('a')] += 1

    for i in range(len(s2)):
        window[ord(s2[i]) - ord('a')] += 1
        if i >= len(s1):  # remove leftmost from window
            window[ord(s2[i - len(s1)]) - ord('a')] -= 1
        if window == s1_count:
            return True
    return False

