def minWindow(s, t):
    if not t: return ""
    need = {}
    for c in t:
        need[c] = need.get(c, 0) + 1

    window = {}
    have, required = 0, len(need)  # unique chars needed
    result, result_len = [-1, -1], float('inf')
    l = 0

    for r in range(len(s)):
        window[s[r]] = window.get(s[r], 0) + 1
        if s[r] in need and window[s[r]] == need[s[r]]:
            have += 1

        while have == required:
            # Update result
            if (r - l + 1) < result_len:
                result = [l, r]
                result_len = r - l + 1
            # Shrink from left
            window[s[l]] -= 1
            if s[l] in need and window[s[l]] < need[s[l]]:
                have -= 1
            l += 1

    l, r = result
    return s[l:r+1] if result_len != float('inf') else ""

